		if(b<0x10)
			sb.append('0');
		return sb.append(Integer.toHexString(b).toUpperCase());
	}

	/**
	 * Encode a character for URLs
	 * @param immune characters not to encode
	 * @param c character to encode
	 * @return the encoded string representing c
	 */
	public String encodeCharacter( char[] immune, Character c )
	{
		String cStr = String.valueOf(c.charValue());
		byte[] bytes;
		StringBuilder sb;

		if(UNENCODED_SET.contains(c))
			return cStr;

		bytes = toUtf8Bytes(cStr);
		sb = new StringBuilder(bytes.length * 3);
		for(byte b : bytes)
			appendTwoUpperHex(sb.append('%'), b);
		return sb.toString();
	}

	/**
	 * {@inheritDoc}
	 * 
	 * Formats all are legal both upper/lower case:
	 *   %hh;
	 *   
	 * @param input
	 * 			encoded character using percent characters (such as URL encoding)
	 */
	public Character decodeCharacter( PushbackString input ) {
		input.mark();
		Character first = input.next();
		if ( first == null || first != '%' ) {
			input.reset();
			return null;
		}

		// Search for 2 hex digits
		StringBuilder sb = new StringBuilder();
		for ( int i=0; i<2; i++ ) {
			Character c = input.nextHex();
			if ( c != null ) {
                sb.append( c );
            } else {
                input.reset();
                return null;
            }
		}

		try {
			// First, try to decode as a single byte
			int b = Integer.parseInt(sb.toString(), 16);
			if (b < 128) {
				return (char) b;
			}

			// It's a multi-byte character.
			// Next, see if we have following bytes that are part of this character.
			// The PushbackString has a lookahead of 4, so this should be safe.
			input.mark();

			// Count the number of leading 1's in the first byte.
			int count = 0;
			if (b >= 192) { // 11000000
				count = 1;
			}
			if (b >= 224) { // 11100000
				count = 2;
			}
			if (b >= 240) { // 11110000
				count = 3;
			}
			if (b >= 248) { // 11111000
				count = 4;
			}
			if (b >= 252) { // 11111100
				count = 5;
			}

			// Allocate a byte buffer
			ByteBuffer bytes = ByteBuffer.allocate(count + 1);
			bytes.put((byte)b);

			// Decode the following bytes
			for (int i=0; i<count; i++) {
				if (!input.peek('%')) {
					input.reset();
					return null;
				}
				input.next(); // Skip '%'

				Character c1 = input.nextHex();
				Character c2 = input.nextHex();
				if (c1 == null || c2 == null) {
					input.reset();
					return null;
				}
				String hex = "" + c1 + c2;
				int b2 = Integer.parseInt(hex, 16);
				// Check for valid UTF-8 continuation byte
				if ((b2 & 0xC0) != 0x80) { // 10000000
					input.reset();
					return null;
				}
				bytes.put((byte)b2);
			}

			// Decode the byte buffer
			bytes.flip();
			CharsetDecoder decoder = Charset.forName("UTF-8").newDecoder();
			decoder.onMalformedInput(CodingErrorAction.REPORT);
			decoder.onUnmappableCharacter(CodingErrorAction.REPORT);
			return decoder.decode(bytes).charAt(0);

		} catch( NumberFormatException | CharacterCodingException e ) {
			input.reset();
			return null;
		}
	}
